import fs from 'fs';

const data = JSON.parse(fs.readFileSync('./s1-nouns-with-offsets.json', 'utf-8'));
const nouns = data.nouns;

console.log('=== s1 补缺名词质量分析 ===\n');
console.log('总名词数:', nouns.length);

console.log('\n按命中次数排序 (前20个，高频优先):');
nouns.slice(0, 20).forEach((n, i) => console.log(`  ${i + 1}. ${n.surface} (${n.offsets.length}次)`));

console.log('\n倒数20个 (低频，命中1次的):');
nouns.slice(-20).forEach((n, i) => console.log(`  ${i + 1}. ${n.surface} (${n.offsets.length}次)`));

console.log('\n中间段随机抽样20个:');
const mid = Math.floor(nouns.length / 2);
nouns.slice(mid - 10, mid + 10).forEach(n => console.log(`  - ${n.surface} (${n.offsets.length}次)`));

// 统计虚词/代词污染情况
const functionWords = ['qui', 'par', 'que', 'elle', 'plus', 'pour', 'nous', 'dans', 'tout', 'est',
  'il', 'la', 'le', 'les', 'de', 'des', 'un', 'une', 'ce', 'cette', 'ces', 'et', 'ou', 'en', 'à',
  'du', 'au', 'aux', 'se', 'ne', 'pas', 'être', 'avoir', 'je', 'tu', 'on', 'ses', 'leur', 'leurs',
  'mon', 'ma', 'mes', 'ton', 'ta', 'tes', 'notre', 'nos', 'votre', 'vos', "l'", "n'", "d'", "j'"];
const polluted = nouns.filter(n => functionWords.includes(n.surface.toLowerCase()));
console.log('\n=== 虚词污染统计 ===');
console.log('疑似虚词/代词条目数:', polluted.length, '/', nouns.length);
console.log('这些条目占用的总命中位置数:', polluted.reduce((s, n) => s + n.offsets.length, 0), '/', data.meta.totalOffsets);
console.log('污染词样例:', polluted.slice(0, 15).map(n => `${n.surface}(${n.offsets.length})`).join(', '));

const confidenceBreakdown = { high: 0, medium: 0, low: 0 };
nouns.forEach(n => n.offsets.forEach(o => confidenceBreakdown[o.confidence] = (confidenceBreakdown[o.confidence] || 0) + 1));
console.log('\n置信度分布:', confidenceBreakdown);

