if (report.summary.batchesWithMediumLow > 0) {
  console.log('\n⚠️  需要人工核对的批次：');
  for (const batch of report.batchesWithMediumLow) {
    console.log(`   批次 ${batch.batchId}: ${batch.nounsWithMediumLow.length} 个名词有 medium/low 位置`);
  }
  console.log('\n人工核对步骤：');
