/**
 * 验证实验组一的正确性：检查提取的名词是否真的在其对应的【【N】】截断内
 * 抽样：前20个 + 中间30个 + 后20个
 */

import fs from 'fs';
import path from 'path';

const GROUP1_OUTPUT = path.join(process.cwd(), 's1-nouns-with-offsets-group1.json');
const SNAPSHOT_DIR = path.join(process.cwd(), 's1-snapshots-group1');
const OUTPUT_PATH = path.join(process.cwd(), 's1-group1-verification-report.json');

console.log('========== 验证实验组一正确性 ==========\n');

const group1Data = JSON.parse(fs.readFileSync(GROUP1_OUTPUT, 'utf-8'));
const allNouns = group1Data.nouns;

console.log(`总名词数: ${allNouns.length}`);

// 抽样策略：前20 + 中间30 + 后20
const samples = [];
const sampleIndices = [];

// 前20个
for (let i = 0; i < Math.min(20, allNouns.length); i++) {
  sampleIndices.push(i);
}

// 中间30个
const midStart = Math.floor((allNouns.length - 30) / 2);
for (let i = midStart; i < midStart + 30 && i < allNouns.length; i++) {
  sampleIndices.push(i);
}

// 后20个
const endStart = Math.max(allNouns.length - 20, 0);
for (let i = endStart; i < allNouns.length; i++) {
  if (!sampleIndices.includes(i)) {
    sampleIndices.push(i);
  }
}

console.log(`抽样数量: ${sampleIndices.length} 个名词\n`);

// 构建 truncId -> snapshot 映射
const truncIdToSnapshot = new Map();

const snapshotFiles = fs.readdirSync(SNAPSHOT_DIR).filter(f => f.endsWith('.json'));
for (const file of snapshotFiles) {
  const snapshot = JSON.parse(fs.readFileSync(path.join(SNAPSHOT_DIR, file), 'utf-8'));
  for (const result of snapshot.results) {
    if (result.found && result.noun) {
      const key = `${snapshot.batchId}-${result.truncId}`;
      if (!truncIdToSnapshot.has(key)) {
        truncIdToSnapshot.set(key, {
          batchId: snapshot.batchId,
          truncId: result.truncId,
          noun: result.noun,
          machineCode: result.machineCode,
          truncation: snapshot.input.truncations.find(t => t.id === result.truncId),
        });
      }
    }
  }
}

console.log(`快照索引构建完成: ${truncIdToSnapshot.size} 个提取记录\n`);

// 验证每个抽样
let correctCount = 0;
let incorrectCount = 0;
let notFoundInSnapshot = 0;

for (const idx of sampleIndices) {
  const noun = allNouns[idx];
  const nounText = noun.noun.toLowerCase();

  // 找到对应的快照数据
  let snapshotEntry = null;
  for (const [key, value] of truncIdToSnapshot.entries()) {
    if (value.noun === noun.noun && value.truncId === noun.truncId) {
      snapshotEntry = value;
      break;
    }
  }

  if (!snapshotEntry || !snapshotEntry.truncation) {
    notFoundInSnapshot++;
    samples.push({
      index: idx,
      noun: noun.noun,
      truncId: noun.truncId,
      chunkKey: noun.chunkKey,
      offsets: noun.offsets,
      verification: {
        status: 'SKIP',
        reason: '未在快照中找到对应的截断数据',
      },
    });
    continue;
  }

  const truncText = snapshotEntry.truncation.text.toLowerCase();
  const isInTruncation = truncText.includes(nounText);

  if (isInTruncation) {
    correctCount++;
  } else {
    incorrectCount++;
  }

  samples.push({
    index: idx,
    noun: noun.noun,
    truncId: noun.truncId,
    machineCode: snapshotEntry.machineCode,
    chunkKey: noun.chunkKey,
    offsets: noun.offsets,
    truncation: {
      start: snapshotEntry.truncation.start,
      end: snapshotEntry.truncation.end,
      page: snapshotEntry.truncation.page,
      text: snapshotEntry.truncation.text,
    },
    verification: {
      status: isInTruncation ? 'CORRECT' : 'INCORRECT',
      isNounInTruncation: isInTruncation,
      conclusion: isInTruncation
        ? '✓ 名词在对应截断内，提取正确'
        : `✗ 名词 "${noun.noun}" 不在截断 "${snapshotEntry.truncation.text}" 内`,
    },
  });
}

const report = {
  meta: {
    experimentGroup: '实验组一（无兜底）',
    totalNouns: allNouns.length,
    sampledNouns: samples.length,
    samplingStrategy: '前20 + 中间30 + 后20',
    generatedAt: new Date().toISOString(),
  },
  summary: {
    correct: correctCount,
    incorrect: incorrectCount,
    notFoundInSnapshot,
    accuracyRate: ((correctCount / (correctCount + incorrectCount)) * 100).toFixed(2) + '%',
  },
  samples,
};

fs.writeFileSync(OUTPUT_PATH, JSON.stringify(report, null, 2), 'utf-8');

console.log('========== 验证完成 ==========');
