function findTruncationForOffset(chunkKey, offsetStart, offsetEnd) {
  const truncs = truncsByChunk.get(chunkKey);
  if (!truncs) return null;
  return truncs.find(t => offsetStart >= t.start && offsetEnd <= t.end) || null;
}

