    console.log(`  LLM 输入 token 位置: 第 ${r.driftTruncStartToken} 个 token (${r.tokenPercentInPrompt}%)`);
    console.log(`  名词: "${r.firstDriftNoun}" (${r.firstDriftConfidence})`);
    console.log(`  截断实际文本: "${r.truncText}"`);
    console.log(`  名词在该截断里: ${r.nounActuallyInTruncText ? '是' : '否 ❌'}`);
    console.log('');
  });
}

/**
 * 诊断 19 个真实飘散批次的 non-high 分布模式
 * 对每个批次：
 *   1. 找出所有 non-high 的名词条目，按 truncId 排序
 *   2. 对每个 non-high 条目，检查该名词是否真的在标记的截断里
 *   3. 判断模式：
 *      - 整体偏移型：大部分 non-high 名词都不在标记的截断里，且编号连续
 *      - 孤立错误型：只有少数 non-high 名词不在标记截断里，其他 non-high 是因为兜底搜索（名词在文本里但在扩窗/全chunk找到）
 */
import fs from 'fs';
import path from 'path';

const SNAPSHOT_DIR = 's1-snapshots-group2';
const DRIFT_ANALYSIS = JSON.parse(fs.readFileSync('s1-group2-drift-token-analysis.json', 'utf-8'));

// 找出 19 个真实飘散的批次 ID
const trueDriftBatchIds = DRIFT_ANALYSIS.results
  .filter(r => r.hasDrift && r.nounActuallyInTruncText === false)
  .map(r => r.batchId);

console.log('=== 诊断 19 个真实飘散批次的 non-high 分布模式 ===\n');
console.log('批次 ID:', trueDriftBatchIds.join(', '), '\n');

const diagnostics = [];

for (const batchId of trueDriftBatchIds) {
  const batch = JSON.parse(fs.readFileSync(path.join(SNAPSHOT_DIR, `batch-${batchId}.json`), 'utf-8'));

  // 找出所有 non-high 条目
  const nonHighEntries = batch.parsedNouns
    .map(entry => {
      const nonHighOffsets = entry.offsets.filter(o => o.confidence !== 'high');
      if (nonHighOffsets.length === 0) return null;

      const trunc = batch.truncations.find(t => t.truncId === entry.truncId);
      const nounInText = trunc ? trunc.text.toLowerCase().includes(entry.noun.toLowerCase()) : false;

      return {
        truncId: entry.truncId,
        noun: entry.noun,
        confidence: nonHighOffsets[0].confidence,
        nounInText,
      };
    })
    .filter(e => e !== null)
    .sort((a, b) => a.truncId - b.truncId);

  const totalNonHigh = nonHighEntries.length;
  const notInText = nonHighEntries.filter(e => !e.nounInText).length;
  const notInTextRatio = totalNonHigh > 0 ? (notInText / totalNonHigh) * 100 : 0;

  // 判断是否连续编号（整体偏移特征）
  const notInTextTruncIds = nonHighEntries.filter(e => !e.nounInText).map(e => e.truncId);
  let consecutiveRuns = 0;
  let currentRun = 1;
  for (let i = 1; i < notInTextTruncIds.length; i++) {
    if (notInTextTruncIds[i] === notInTextTruncIds[i-1] + 1) {
      currentRun++;
    } else {
      if (currentRun >= 3) consecutiveRuns++;
      currentRun = 1;
    }
  }
  if (currentRun >= 3) consecutiveRuns++;

  const pattern = 
    notInTextRatio >= 60 && consecutiveRuns > 0 ? '整体偏移型' :
    notInTextRatio >= 30 && notInText >= 5 ? '混合型（需重跑）' :
    '孤立错误型（兜底可处理）';

  diagnostics.push({
    batchId,
    totalTruncations: batch.truncations.length,
    totalNonHigh,
    notInText,
    notInTextRatio: parseFloat(notInTextRatio.toFixed(1)),
    consecutiveRuns,
    pattern,
    firstDriftTruncId: DRIFT_ANALYSIS.results.find(r => r.batchId === batchId)?.firstDriftTruncId,
  });

  console.log(`批次 ${batchId}:`);
  console.log(`  截断总数: ${batch.truncations.length}`);
  console.log(`  non-high 名词总数: ${totalNonHigh}`);
  console.log(`  其中"名词不在标记截断里": ${notInText} (${notInTextRatio.toFixed(1)}%)`);
  console.log(`  连续编号段(≥3个): ${consecutiveRuns}`);
  console.log(`  模式判断: ${pattern}`);
  console.log('');
}

const needRerun = diagnostics.filter(d => d.pattern !== '孤立错误型（兜底可处理）');

console.log('\n=== 汇总 ===');
console.log('真实飘散批次总数:', diagnostics.length);
console.log('整体偏移型/混合型（建议重跑）:', needRerun.length);
console.log('孤立错误型（不需重跑）:', diagnostics.length - needRerun.length);

fs.writeFileSync('s1-group2-rerun-recommendation.json', JSON.stringify({
  meta: {
    description: 'non-high 分布模式诊断与重跑建议',
    trueDriftBatches: diagnostics.length,
    needRerunBatches: needRerun.length,
    canSkipBatches: diagnostics.length - needRerun.length,
  },
  diagnostics,
  needRerun: needRerun.map(d => d.batchId),
}, null, 2), 'utf-8');

console.log('\n建议重跑的批次:', needRerun.map(d => d.batchId).join(', '));
console.log('\n完整诊断已保存至: s1-group2-rerun-recommendation.json');

/**
 * 提取 19 个真实飘散批次的输入输出，标记问题点
 * 对每个批次生成一个可读的 markdown 文件：
 *   - 批次元数据
 *   - 完整 prompt（输入）
 *   - 完整 LLM 原始输出
 *   - parsedNouns 里所有 non-high 条目，标记是否在对应截断里
 */
import fs from 'fs';
import path from 'path';

const SNAPSHOT_DIR = 's1-snapshots-group2';
const OUTPUT_DIR = 's1-drift-review';
const RERUN_DATA = JSON.parse(fs.readFileSync('s1-group2-rerun-recommendation.json', 'utf-8'));

if (!fs.existsSync(OUTPUT_DIR)) {
  fs.mkdirSync(OUTPUT_DIR);
}

const trueDriftBatchIds = RERUN_DATA.diagnostics.map(d => d.batchId);

console.log(`提取 ${trueDriftBatchIds.length} 个批次的输入输出...\n`);

for (const batchId of trueDriftBatchIds) {
  const batch = JSON.parse(fs.readFileSync(path.join(SNAPSHOT_DIR, `batch-${batchId}.json`), 'utf-8'));
  const diagnostic = RERUN_DATA.diagnostics.find(d => d.batchId === batchId);

  let md = `# 批次 ${batchId} - ${diagnostic.pattern}\n\n`;

  md += `## 元数据\n\n`;
  md += `- **截断总数**: ${batch.truncations.length}\n`;
  md += `- **non-high 名词数**: ${diagnostic.totalNonHigh}\n`;
  md += `- **其中不在标记截断里**: ${diagnostic.notInText} (${diagnostic.notInTextRatio}%)\n`;
  md += `- **连续编号段**: ${diagnostic.consecutiveRuns}\n`;
  md += `- **首次飘散点**: 【【${diagnostic.firstDriftTruncId}】】\n`;
  md += `- **模式**: ${diagnostic.pattern}\n\n`;

  md += `---\n\n`;

  // 输入 prompt（前 3000 字符 + 后 3000 字符，中间省略）
  md += `## 输入 Prompt\n\n`;
  md += `\`\`\`\n`;
  if (batch.prompt.length <= 6000) {
    md += batch.prompt;
  } else {
    md += batch.prompt.substring(0, 3000);
    md += `\n\n... [省略 ${Math.floor((batch.prompt.length - 6000) / 1000)}k 字符] ...\n\n`;
    md += batch.prompt.substring(batch.prompt.length - 3000);
  }
  md += `\n\`\`\`\n\n`;

  md += `---\n\n`;

  // LLM 原始输出（前 3000 字符 + 后 3000 字符）
  md += `## LLM 原始输出\n\n`;
  md += `\`\`\`\n`;
  if (batch.rawOutput.length <= 6000) {
    md += batch.rawOutput;
  } else {
    md += batch.rawOutput.substring(0, 3000);
    md += `\n\n... [省略 ${Math.floor((batch.rawOutput.length - 6000) / 1000)}k 字符] ...\n\n`;
    md += batch.rawOutput.substring(batch.rawOutput.length - 3000);
  }
  md += `\n\`\`\`\n\n`;

  md += `---\n\n`;

  // 提取所有 non-high 条目
  const nonHighEntries = [];
  for (const entry of batch.parsedNouns) {
    const nonHighOffsets = entry.offsets.filter(o => o.confidence !== 'high');
    if (nonHighOffsets.length === 0) continue;

    const trunc = batch.truncations.find(t => t.truncId === entry.truncId);
    const nounInText = trunc ? trunc.text.toLowerCase().includes(entry.noun.toLowerCase()) : false;

    nonHighEntries.push({
      truncId: entry.truncId,
      noun: entry.noun,
      confidence: nonHighOffsets[0].confidence,
      truncText: trunc ? trunc.text : null,
      nounInText,
    });
  }

  md += `## Non-high 名词详情 (${nonHighEntries.length} 个)\n\n`;
  md += `| 截断编号 | 名词 | 置信度 | 在截断里? | 截断实际文本 |\n`;
  md += `|---|---|---|---|---|\n`;

  for (const entry of nonHighEntries) {
    const flag = entry.nounInText ? '✅' : '❌ **问题**';
    const truncText = entry.truncText ? entry.truncText.substring(0, 60) + (entry.truncText.length > 60 ? '...' : '') : 'N/A';
    md += `| 【【${entry.truncId}】】 | ${entry.noun} | ${entry.confidence} | ${flag} | ${truncText} |\n`;
  }

  md += `\n---\n\n`;

  // 如果是整体偏移型，给出前 20 个截断的完整对照
  if (diagnostic.pattern !== '孤立错误型（兜底可处理）') {
    md += `## 首次飘散点附近的截断详情\n\n`;
    md += `展示【【${diagnostic.firstDriftTruncId}】】前后各 5 个截断的完整文本，便于人工核对：\n\n`;

    const startIdx = Math.max(0, diagnostic.firstDriftTruncId - 5);
    const endIdx = Math.min(batch.truncations.length, diagnostic.firstDriftTruncId + 10);

    for (let i = startIdx; i < endIdx; i++) {
      const trunc = batch.truncations[i];
      const isFirstDrift = trunc.truncId === diagnostic.firstDriftTruncId;

      md += `### 【【${trunc.truncId}】】${isFirstDrift ? ' ⚠️ **首次飘散点**' : ''}\n\n`;
      md += `\`\`\`\n${trunc.text}\n\`\`\`\n\n`;

      // 检查这个截断对应的 parsedNouns
      const relatedNouns = batch.parsedNouns.filter(n => n.truncId === trunc.truncId);
      if (relatedNouns.length > 0) {
        md += `**LLM 标记的名词**：\n`;
        for (const noun of relatedNouns) {
          const conf = noun.offsets[0]?.confidence || 'unknown';
          const inText = trunc.text.toLowerCase().includes(noun.noun.toLowerCase());
          const flag = inText ? '✅' : '❌';
          md += `- ${noun.noun} (${conf}) ${flag}\n`;
        }
        md += `\n`;
      }
    }
  }

  const filename = `batch-${batchId}-${diagnostic.pattern.replace(/[^a-z0-9]/gi, '-')}.md`;
  fs.writeFileSync(path.join(OUTPUT_DIR, filename), md, 'utf-8');

  console.log(`✓ 批次 ${batchId} -> ${filename}`);
}

console.log(`\n所有文件已保存到: ${OUTPUT_DIR}/`);
