  'très','bien','encore','déjà','toujours','jamais','aussi','peut','peu',
]);

function isFunctionWordOnly(text) {
  // 去掉标点，分词
  const cleaned = text.replace(/[.,;:!?()«»""''\u2026\-]/g, ' ').trim();
  const words = cleaned.split(/\s+/).filter(w => w.length > 0);
