  'ici','là','maintenant','hier','demain','aujourd','hui',
]);

// 常见动词（不定式、过去分词、现在分词）
const VERBS = new Set([
  'cherché','appréhender','marqué','devront','finir','être','recentrés','transformer','inventer',
  'dire','appartenir','parait','furent','souligne','souligner','va','vont','peut','peuvent',
