]);

function hasNoun(text) {
  // 清理标点
  const cleaned = text.replace(/[.,;:!?()«»""''\u2026\-*]/g, ' ').trim();
  const words = cleaned.split(/\s+/).filter(w => w.length > 0);

  for (const word of words) {
    const lw = word.toLowerCase();

    // 跳过虚词和动词
    if (FUNCTION_WORDS.has(lw) || VERBS.has(lw)) continue;

    // 跳过单字母残片
    if (word.length <= 1) continue;

    // 如果是已知名词，肯定有
    if (KNOWN_NOUNS.has(lw)) return { hasNoun: true, nouns: [word] };

    // 其他多音节词（长度 >= 3），可能是名词
    if (word.length >= 3) {
      // 排除明显的形容词词尾（但不排除名词化形容词）
