md += `|------|--------|----------------|------------------|-------------|\n`;

for (const r of needReview) {
  md += `| ${r.batchId} | 【【${r.truncId}】】 | ${r.promptTruncText} | ${r.detectedNouns.join(', ')} | ${r.llmOutputText} |\n`;
