    // 跳过代词
    if (/^(chacun|chacune|quelqu|aucun|aucune)$/i.test(lw)) continue;

    // 只接受明确的名词词尾：-tion, -sion, -eur, -age, -isme, -ité, -té, -esse, -ance, -ence
