// ============ 拓扑链召回（新架构）============
// 策略：
// 1. 分数过滤：只保留 score >= SCORE_THRESHOLD 的名词
// 2. 展开所有偏移量：从终词表获取每个高分名词的所有去重位移
// 3. 名词邻居：每个偏移量在终词表中找前后各 TOPOLOGY_WINDOW 个名词（基于终词表位置，非字符）
// 4. 拓扑链区间：第一个名词首字符位移 ~ 最后一个名词末字符位移
// 5. 区间去重取并集：合并重叠拓扑链
// 6. 按区间召回原文：用于推理模型

const SCORE_THRESHOLD = 80; // 分数阈值

// 预建：每个 chunk 内所有名词出现位置（按 start 升序），用于快速找邻居
function buildChunkNounIndex() {
  const index = new Map(); // chunkKey -> [{ nounId, nounSurface, start, end }]
  for (const noun of nounIndex.nouns) {
    for (const { chunkKey, start, end } of noun.offsets) {
      if (!index.has(chunkKey)) index.set(chunkKey, []);
      index.get(chunkKey).push({ nounId: noun.id, nounSurface: noun.surface, start, end });
    }
  }
  // 每个 chunk 内按 start 升序排序
  for (const [, occurrences] of index) {
    occurrences.sort((a, b) => a.start - b.start);
  }
  return index;
}

const chunkNounIndex = buildChunkNounIndex();

// 在终词表中查找某个偏移量位置的前后名词邻居
// 返回：[neighborSurface, ...]（仅名词表面形式）
function findNounNeighbors(chunkKey, targetStart) {
  const occurrences = chunkNounIndex.get(chunkKey);
  if (!occurrences || occurrences.length === 0) return [];

  // 二分查找：找第一个 start > targetStart 的位置，然后取其前后的邻居
  let lo = 0, hi = occurrences.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (occurrences[mid].start <= targetStart) lo = mid + 1;
    else hi = mid;
  }

  const neighbors = [];
  // 取前 TOPOLOGY_WINDOW 个邻居（lo 位置本身是 target 位置，不取）
  for (let i = Math.max(0, lo - TOPOLOGY_WINDOW); i < lo; i++) {
    neighbors.push(occurrences[i].nounSurface);
  }
  // 取后 TOPOLOGY_WINDOW 个邻居
  for (let i = lo; i < Math.min(occurrences.length, lo + TOPOLOGY_WINDOW); i++) {
    neighbors.push(occurrences[i].nounSurface);
  }

  return [...new Set(neighbors)]; // 去重
}

// 构建单个高分名词的拓扑链（每个偏移量一条链）
function buildTopologyChainsForNoun(nounId) {
  const nounEntry = nounIndex.nouns.find((n) => n.id === nounId);
  if (!nounEntry) return [];

  const chains = [];
  for (const { chunkKey, start, end } of nounEntry.offsets) {
    const entry = chunkByKey.get(chunkKey);
    if (!entry) continue;

    const neighbors = findNounNeighbors(chunkKey, start);
    if (neighbors.length === 0) continue;

    chains.push({
      chunkKey,
      page: entry.page,
      // 拓扑链区间：第一个邻居首字符 ~ 最后一个邻居末字符
      // 注意：neighbors 是去重的表面形式，需要重新找对应的实际偏移量
      // 简化处理：取 targetStart 前第1个邻居的 start 和后第1个邻居的 end
      chainNeighbors: neighbors,
      // 区间起始：取 targetStart 之前最近邻的 start
      // 区间结束：取 targetStart 之后最远邻的 end（按 start 排序后最后一个）
    });
  }
  return chains;
}

// 更精确：基于终词表 occurrence 位置确定拓扑链区间
function buildTopologyChainsForNounV2(nounId) {
  const nounEntry = nounIndex.nouns.find((n) => n.id === nounId);
  if (!nounEntry) return [];

  const chains = [];
  for (const { chunkKey, start, end } of nounEntry.offsets) {
    const occurrences = chunkNounIndex.get(chunkKey);
    if (!occurrences || occurrences.length === 0) continue;

    // 二分查找 targetStart 在 occurrence 列表中的位置
    let lo = 0, hi = occurrences.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (occurrences[mid].start <= start) lo = mid + 1;
      else hi = mid;
    }

    // 取前 TOPOLOGY_WINDOW 个邻居
    const beforeStart = Math.max(0, lo - TOPOLOGY_WINDOW);
    const beforeEnd = lo; // 不含 lo（target 自身）

    // 取后 TOPOLOGY_WINDOW 个邻居
    const afterStart = lo + 1; // 不含 lo（target 自身）
    const afterEnd = Math.min(occurrences.length, lo + 1 + TOPOLOGY_WINDOW);

    // 合并邻居（去重）
    const neighborSet = new Set();
    for (let i = beforeStart; i < beforeEnd; i++) neighborSet.add(occurrences[i].nounSurface);
    for (let i = afterStart; i < afterEnd; i++) neighborSet.add(occurrences[i].nounSurface);
    const neighbors = [...neighborSet];

    if (neighbors.length === 0) continue;

    // 拓扑链区间：最前邻居的 start ~ 最后邻居的 end
    const chainStart = occurrences[beforeStart].start;
    const lastIdx = Math.min(occurrences.length - 1, lo + TOPOLOGY_WINDOW);
    const chainEnd = occurrences[Math.max(lo - 1, beforeEnd - 1, afterStart)].end;

    // 重新计算 chainEnd：取 afterEnd-1 的 end
    const actualChainEnd = occurrences[Math.min(afterEnd - 1, occurrences.length - 1)].end;

    chains.push({
      chunkKey,
      page: chunkByKey.get(chunkKey)?.page || 0,
      offset: start,
      neighbors,
      chainStart,
      chainEnd: actualChainEnd,
    });
  }
  return chains;
}

// 合并重叠拓扑链区间（按 chunkKey 分组合并）
function mergeTopologyIntervals(chains) {
  if (chains.length === 0) return [];

  // 按 chunkKey 分组
  const byChunk = new Map();
  for (const c of chains) {
    if (!byChunk.has(c.chunkKey)) byChunk.set(c.chunkKey, []);
    byChunk.get(c.chunkKey).push(c);
  }

  const merged = [];

  for (const [chunkKey, chunkChains] of byChunk) {
    // 按 chainStart 排序
    chunkChains.sort((a, b) => a.chainStart - b.chainStart);

    let curStart = chunkChains[0].chainStart;
    let curEnd = chunkChains[0].chainEnd;

    for (let i = 1; i < chunkChains.length; i++) {
      const { chainStart, chainEnd } = chunkChains[i];
      if (chainStart <= curEnd) {
        // 重叠或相邻，合并
        curEnd = Math.max(curEnd, chainEnd);
      } else {
        // 不重叠，保存当前区间，开新区间
        merged.push({ chunkKey, chainStart: curStart, chainEnd: curEnd });
        curStart = chainStart;
        curEnd = chainEnd;
      }
    }
    merged.push({ chunkKey, chainStart: curStart, chainEnd: curEnd });
  }

  return merged;
}

// 按区间召回原文
function recallByIntervals(intervals) {
  const results = [];
  for (const { chunkKey, chainStart, chainEnd } of intervals) {
    const entry = chunkByKey.get(chunkKey);
    if (!entry) continue;
    const text = entry.text.slice(chainStart, chainEnd);
    results.push({ chunkKey, page: entry.page, chainStart, chainEnd, text });
  }
  return results;
}

// 旧函数保留（兼容），但主流程改用新架构
function getTopologyBookKeys(nounId) {
  const chains = buildTopologyChainsForNounV2(nounId);
  const bookKeys = new Set();
  for (const c of chains) if (c.chunkKey) bookKeys.add(c.chunkKey);
  return { chains, bookKeys: [...bookKeys] };
}

function recallByBookKey(chunkKey) {
  const entry = chunkByKey.get(chunkKey);
  return entry ? entry.text : null;
}

