function mergeTopologyIntervals(chains) {
  if (chains.length === 0) return [];

  // 对于跨 chunk 的拓扑链，将其拆分为每个 chunk 的区间段
  const expandedIntervals = [];

  for (const chain of chains) {
    if (!chain.crossChunk) {
      // 单 chunk 内的链，直接添加
      expandedIntervals.push({
        chunkKey: chain.chunkKey,
        chainStart: chain.chainStart,
        chainEnd: chain.chainEnd,
        page: chain.page,
      });
    } else {
      // 跨 chunk 的链，按阅读序找出所有涉及的 chunk 区间
      const involvedChunks = chain.involvedChunks;

      // 找出这条链在全局 occurrence 中的范围
      let startIdx = -1, endIdx = -1;
      for (let i = 0; i < globalNounOccurrences.length; i++) {
        const occ = globalNounOccurrences[i];
        if (startIdx === -1 && occ.chunkKey === chain.chainStartChunk && occ.start === chain.chainStart) {
          startIdx = i;
        }
        if (occ.chunkKey === chain.chainEndChunk && occ.end === chain.chainEnd) {
          endIdx = i;
          break;
        }
      }

      if (startIdx === -1 || endIdx === -1) continue;

      // 按 chunk 分组，找每个 chunk 的起止范围
      const chunkRanges = new Map(); // chunkKey -> { start, end, page }
      for (let i = startIdx; i <= endIdx; i++) {
        const occ = globalNounOccurrences[i];
        if (!chunkRanges.has(occ.chunkKey)) {
          chunkRanges.set(occ.chunkKey, { start: occ.start, end: occ.end, page: occ.page });
        } else {
          const range = chunkRanges.get(occ.chunkKey);
          range.start = Math.min(range.start, occ.start);
          range.end = Math.max(range.end, occ.end);
        }
      }

      // 将每个 chunk 的区间加入待合并列表
      for (const [chunkKey, range] of chunkRanges) {
        expandedIntervals.push({
          chunkKey,
          chainStart: range.start,
          chainEnd: range.end,
          page: range.page,
        });
      }
    }
  }

  // 按 chunkKey 分组合并重叠区间
  const byChunk = new Map();
  for (const interval of expandedIntervals) {
    if (!byChunk.has(interval.chunkKey)) byChunk.set(interval.chunkKey, []);
    byChunk.get(interval.chunkKey).push(interval);
  }

  const merged = [];
  for (const [chunkKey, intervals] of byChunk) {
    // 按 chainStart 排序
    intervals.sort((a, b) => a.chainStart - b.chainStart);

    let curStart = intervals[0].chainStart;
    let curEnd = intervals[0].chainEnd;
    let curPage = intervals[0].page;

    for (let i = 1; i < intervals.length; i++) {
      const { chainStart, chainEnd, page } of intervals[i];
      if (chainStart <= curEnd) {
        // 重叠或相邻，合并
        curEnd = Math.max(curEnd, chainEnd);
      } else {
